import { defineConfig } from "@playwright/test";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));

// The end-to-end run: a demo gateway (no AI key, no Docker) and the built page served by
// vite preview, both started here. The screens are checked and photographed into
// docs/screenshots, so the documentation is regenerated by the test that proves it.
export const GATEWAY = "http://127.0.0.1:7498";
export const PAGE = "http://127.0.0.1:4199";
// The gateway that asks for a sign-in, and the page in front of it.
export const LOGIN_GATEWAY = "http://127.0.0.1:7497";
export const LOGIN_PAGE = "http://127.0.0.1:4198";
export const WEBHOOK_PORT = 7499;
export const ROOT = path.resolve(here, "../../..");
export const SHOTS = path.join(ROOT, "docs/screenshots");
export const STATE = path.join(here, ".state.json");
// What the stub of the outside world (a Slack webhook, an ntfy server) received, one line each.
export const HOOK_LOG = path.join(here, ".hooks.log");

export default defineConfig({
  testDir: here,
  testMatch: /.*\.spec\.ts/,
  globalSetup: path.join(here, "global-setup.ts"),
  timeout: 60_000,
  expect: { timeout: 15_000 },
  workers: 1,
  fullyParallel: false,
  retries: 0,
  reporter: process.env.CI
    ? [["list"], ["html", { open: "never", outputFolder: path.join(here, "report") }]]
    : "list",
  outputDir: path.join(here, "test-results"),
  use: {
    baseURL: PAGE,
    viewport: { width: 1440, height: 900 },
    deviceScaleFactor: 1,
    colorScheme: "dark",
    trace: "retain-on-failure",
  },
  webServer: [
    {
      command:
        "rm -rf desktop/frontend/e2e/.data && go run ./cmd/kitties -demo -config desktop/frontend/e2e/kitties.yaml gateway",
      cwd: ROOT,
      url: GATEWAY + "/v1/health",
      reuseExistingServer: false,
      timeout: 180_000,
      stdout: "ignore",
      stderr: "pipe",
    },
    {
      command:
        "rm -rf desktop/frontend/e2e/.data-login && go run ./cmd/kitties -demo -config desktop/frontend/e2e/kitties-login.yaml gateway",
      cwd: ROOT,
      url: LOGIN_GATEWAY + "/v1/health",
      reuseExistingServer: false,
      timeout: 180_000,
      stdout: "ignore",
      stderr: "pipe",
    },
    {
      command: "npx vite preview --host 127.0.0.1 --port 4198 --strictPort",
      cwd: path.resolve(here, ".."),
      url: LOGIN_PAGE,
      env: { KITTIES_GATEWAY: LOGIN_GATEWAY },
      reuseExistingServer: false,
      timeout: 60_000,
    },
    {
      command: "npx vite preview --host 127.0.0.1 --port 4199 --strictPort",
      cwd: path.resolve(here, ".."),
      url: PAGE,
      env: { KITTIES_GATEWAY: GATEWAY },
      reuseExistingServer: false,
      timeout: 60_000,
    },
  ],
});
